<?php
declare(strict_types=1);require_once __DIR__.'/bootstrap.php';if(session_status()!==PHP_SESSION_ACTIVE)session_start();function pdh(mixed$v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}$id=(int)($_GET['id']??0);$pdo=app_database();$s=$pdo->prepare("SELECT p.*,f.*,(SELECT filename FROM produit_image pi WHERE pi.produit_id=p.id_produit ORDER BY pi.position,pi.date_upload DESC LIMIT 1) image FROM produit p LEFT JOIN produit_fiche f ON f.produit_id=p.id_produit WHERE p.id_produit=?");$s->execute([$id]);$product=$s->fetch(PDO::FETCH_ASSOC);if(!$product){http_response_code(404);exit('Produit introuvable.');}$s=$pdo->prepare('SELECT * FROM produit_specification WHERE produit_id=? ORDER BY position,id');$s->execute([$id]);$specs=$s->fetchAll(PDO::FETCH_ASSOC);$related=[];if($product['categorie']){$s=$pdo->prepare("SELECT p.id_produit,p.designation,p.dernier_prix,p.prix_moyen,(SELECT filename FROM produit_image pi WHERE pi.produit_id=p.id_produit ORDER BY pi.position,pi.date_upload DESC LIMIT 1) image FROM produit p JOIN produit_fiche f ON f.produit_id=p.id_produit WHERE f.categorie=? AND p.id_produit<>? ORDER BY p.date_creation DESC LIMIT 4");$s->execute([$product['categorie'],$id]);$related=$s->fetchAll(PDO::FETCH_ASSOC);}if(!$related){$s=$pdo->prepare("SELECT p.id_produit,p.designation,p.dernier_prix,p.prix_moyen,(SELECT filename FROM produit_image pi WHERE pi.produit_id=p.id_produit ORDER BY pi.position,pi.date_upload DESC LIMIT 1) image FROM produit p WHERE p.id_produit<>? ORDER BY p.date_creation DESC LIMIT 4");$s->execute([$id]);$related=$s->fetchAll(PDO::FETCH_ASSOC);}$price=(float)($product['dernier_prix']?:$product['prix_moyen']);$image=$product['image']?'photo/produits/'.$product['image']:'';
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=pdh($product['designation'])?> | FIDEST</title><link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css" rel="stylesheet"><link rel="stylesheet" href="branding.css.php"><link rel="stylesheet" href="css/public-shop.css"><style>.detail-shell{width:min(1280px,calc(100% - 30px));margin:28px auto 70px}.detail-breadcrumb{margin-bottom:18px;color:#777b8d;font-size:.75rem}.detail-breadcrumb a{color:var(--brand-primary);font-weight:800;text-decoration:none}.product-detail{display:grid;grid-template-columns:minmax(320px,.9fr) minmax(0,1.1fr);gap:38px;padding:30px;background:#fff;border:1px solid #e4e5ec;border-radius:25px}.detail-image{display:grid;min-height:460px;place-items:center;overflow:hidden;background:#f4f4f7;border-radius:19px}.detail-image img{width:100%;height:100%;max-height:560px;object-fit:contain}.detail-image i{color:#bbbcc7;font-size:5rem}.detail-copy .category{color:#d19b00;font-size:.7rem;font-weight:900;letter-spacing:.13em}.detail-copy h1{margin:10px 0;color:var(--brand-primary);font:800 clamp(2rem,4vw,3.3rem)/1.05 var(--brand-font-heading)}.detail-ref{color:#8c8f9f;font-size:.72rem}.detail-summary{margin:22px 0;color:#656879;line-height:1.7}.detail-price{margin:18px 0;color:var(--brand-primary);font:800 1.8rem var(--brand-font-heading)}.detail-price small{font-size:.65rem;color:#999}.detail-actions{display:flex;gap:10px}.detail-add{min-height:52px;padding:0 24px;color:var(--brand-primary);background:var(--brand-accent);border:0;border-radius:12px;font-weight:900}.detail-chat{min-height:52px;padding:0 20px;color:var(--brand-primary);background:#ececf3;border:0;border-radius:12px;font-weight:800}.detail-facts{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:25px}.detail-facts div{padding:13px;background:#f7f7fa;border-radius:11px}.detail-facts small,.detail-facts strong{display:block}.detail-facts small{color:#999;font-size:.62rem}.detail-facts strong{margin-top:4px;font-size:.74rem}.detail-content{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:22px}.detail-panel{padding:25px;background:#fff;border:1px solid #e4e5ec;border-radius:20px}.detail-panel h2,.similar-section h2{margin:0 0 17px;color:var(--brand-primary);font:800 1.25rem var(--brand-font-heading)}.detail-panel p{color:#656879;line-height:1.7;white-space:pre-line}.spec-table{width:100%;border-collapse:collapse}.spec-table td{padding:11px;border-bottom:1px solid #ececf1;font-size:.78rem}.spec-table td:first-child{color:#777b8d}.spec-table td:last-child{font-weight:800}.similar-section{margin-top:45px}.similar-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.similar-card{overflow:hidden;color:inherit;background:#fff;border:1px solid #e4e5ec;border-radius:16px;text-decoration:none}.similar-card img,.similar-placeholder{display:grid;width:100%;height:170px;object-fit:cover;place-items:center;color:#bbb;background:#f1f1f5;font-size:2rem}.similar-card div:last-child{padding:14px}.similar-card strong{display:block;height:40px;overflow:hidden;font-size:.78rem}.similar-card span{display:block;margin-top:8px;color:var(--brand-primary);font-weight:900;font-size:.78rem}@media(max-width:800px){.detail-shell{margin-top:14px}.product-detail{grid-template-columns:1fr;padding:16px;gap:20px}.detail-image{min-height:330px}.detail-content{grid-template-columns:1fr}.similar-grid{grid-template-columns:1fr 1fr}.detail-actions{flex-direction:column}.detail-actions button{width:100%}}@media(max-width:480px){.detail-image{min-height:270px}.detail-facts{grid-template-columns:1fr}.similar-grid{grid-template-columns:1fr 1fr}.similar-card img,.similar-placeholder{height:130px}}</style></head><body><header class="market-header"><a class="market-logo" href="boutique_publique.php"><img src="img/logo_fidest.png" alt="FIDEST"><span>BOUTIQUE<small>Solutions professionnelles</small></span></a><div></div><a class="cart-trigger" href="boutique_publique.php"><span class="cart-trigger__icon"><i class="fa-solid fa-store"></i></span><span>Catalogue<small>Retour aux produits</small></span></a></header><main class="detail-shell"><div class="detail-breadcrumb"><a href="boutique_publique.php">Boutique</a> / <?=pdh($product['categorie']?:'Produit')?> / <?=pdh($product['designation'])?></div><section class="product-detail"><div class="detail-image"><?php if($image):?><img src="<?=pdh($image)?>" alt="<?=pdh($product['designation'])?>"><?php else:?><i class="fa-solid fa-box-open"></i><?php endif?></div><div class="detail-copy"><div class="category"><?=pdh($product['categorie']?:'ÉQUIPEMENT PROFESSIONNEL')?></div><h1><?=pdh($product['designation'])?></h1><div class="detail-ref">Réf. FID-<?=$id?><?= $product['reference_fabricant']?' · Fabricant '.pdh($product['reference_fabricant']):''?></div><p class="detail-summary"><?=pdh($product['description_courte']?:'Une solution professionnelle sélectionnée par FIDEST. Contactez notre équipe pour obtenir toutes les informations adaptées à votre besoin.')?></p><div class="detail-price"><?=$price>0?number_format($price,0,',',' ').' FCFA':'Prix sur demande'?> <small><?=$price>0?'HT':''?></small></div><div class="detail-actions"><button class="detail-add" id="detailAdd"><i class="fa-solid fa-cart-plus"></i> Ajouter au panier</button><button class="detail-chat" id="detailChat"><i class="fa-solid fa-comments"></i> Poser une question</button></div><div class="detail-facts"><div><small>Disponibilité</small><strong><?=(int)$product['stock']>0?'En stock':'Sur commande'?></strong></div><div><small>Garantie</small><strong><?=pdh($product['garantie']?:'Nous consulter')?></strong></div><div><small>Livraison</small><strong><?=pdh($product['delai_livraison']?:'À confirmer')?></strong></div></div></div></section><div class="detail-content"><section class="detail-panel"><h2>Description du produit</h2><p><?=pdh($product['description_longue']?:$product['description_courte']?:'Les informations détaillées seront prochainement disponibles. Notre équipe peut vous conseiller immédiatement.')?></p></section><section class="detail-panel"><h2>Fiche technique</h2><?php if($specs):?><table class="spec-table"><?php foreach($specs as$spec):?><tr><td><?=pdh($spec['libelle'])?></td><td><?=pdh($spec['valeur'])?></td></tr><?php endforeach?></table><?php else:?><p>Les caractéristiques techniques sont disponibles sur demande.</p><?php endif?></section></div><section class="similar-section"><h2>Produits similaires</h2><div class="similar-grid"><?php foreach($related as$item):$relatedPrice=(float)($item['dernier_prix']?:$item['prix_moyen']);?><a class="similar-card" href="produit.php?id=<?=$item['id_produit']?>"><?php if($item['image']):?><img src="photo/produits/<?=pdh($item['image'])?>" alt="" loading="lazy"><?php else:?><span class="similar-placeholder"><i class="fa-solid fa-box"></i></span><?php endif?><div><strong><?=pdh($item['designation'])?></strong><span><?=$relatedPrice>0?number_format($relatedPrice,0,',',' ').' FCFA':'Sur devis'?></span></div></a><?php endforeach?></div></section></main><?php $chatProductId=$id;include __DIR__.'/partials/public_chat.php';?><script>document.getElementById('detailChat').onclick=()=>document.getElementById('publicChatTrigger').click();document.getElementById('detailAdd').onclick=()=>{let cart=[];try{cart=JSON.parse(localStorage.getItem('fidest_public_cart')||'[]')}catch(e){}const id=<?=$id?>,line=cart.find(item=>item.id===id);if(line)line.quantity++;else cart.push({id,name:<?=json_encode($product['designation'],JSON_UNESCAPED_UNICODE)?>,price:<?=$price?>,image:<?=json_encode($image)?>,quantity:1});localStorage.setItem('fidest_public_cart',JSON.stringify(cart));location.href='boutique_publique.php'};</script></body></html>
